1	import { useState, useRef } from "react";
2	import { useParams, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Label } from "@/components/ui/label";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { toast } from "sonner";
10	import {
11	  CheckCircle2,
12	  Upload,
13	  FileText,
14	  X,
15	  Loader2,
16	  ExternalLink,
17	  Briefcase,
18	} from "lucide-react";
19	
20	const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB
21	const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
22	const ALLOWED_MIME = [
23	  "application/pdf",
24	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
25	  "application/msword",
26	  "text/plain",
27	  "application/rtf",
28	  "text/rtf",
29	];
30	
31	function hasAllowedExtension(filename: string): boolean {
32	  const lower = filename.toLowerCase();
33	  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
34	}
35	
36	interface JobInfo {
37	  id: string;
38	  title: string;
39	  status: string;
40	  job_description: string;
41	}
42	
43	export default function Apply() {
44	  const { jobId } = useParams<{ jobId: string }>();
45	  const fileInputRef = useRef<HTMLInputElement>(null);
46	
47	  const [name, setName] = useState("");
48	  const [email, setEmail] = useState("");
49	  const [phone, setPhone] = useState("");
50	  const [linkedinUrl, setLinkedinUrl] = useState("");
51	  const [resumeFile, setResumeFile] = useState<File | null>(null);
52	  const [dragOver, setDragOver] = useState(false);
53	  const [submitting, setSubmitting] = useState(false);
54	  const [submitted, setSubmitted] = useState(false);
55	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
56	
57	  // Fetch minimal job info — no auth required via RPC
58	  const {
59	    data: job,
60	    isLoading: jobLoading,
61	    error: jobError,
62	  } = useQuery<JobInfo | null>({
63	    queryKey: ["apply-job-info", jobId],
64	    queryFn: async () => {
65	      if (!jobId) return null;
66	      const { data, error } = await supabase.rpc("get_job_apply_info", {
67	        p_job_id: jobId,
68	      });
69	      if (error) throw new Error(error.message);
70	      if (!data || (Array.isArray(data) && data.length === 0)) return null;
71	      const row = Array.isArray(data) ? data[0] : data;
72	      return row as JobInfo;
73	    },
74	    enabled: !!jobId,
75	    retry: 1,
76	    staleTime: 60_000,
77	  });
78	
79	  const handleFileSelect = (file: File) => {
80	    if (file.size > MAX_FILE_BYTES) {
81	      toast.error("File exceeds 10MB limit");
82	      return;
83	    }
84	    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
85	      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
86	      return;
87	    }
88	    setResumeFile(file);
89	    setFieldErrors((prev) => ({ ...prev, resume: "" }));
90	  };
91	
92	  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
93	    e.preventDefault();
94	    setDragOver(false);
95	    const file = e.dataTransfer.files[0];
96	    if (file) handleFileSelect(file);
97	  };
98	
99	  const validate = (): boolean => {
100	    const errors: Record<string, string> = {};
101	    if (!name.trim()) errors.name = "Name is required";
102	    if (!email.trim()) errors.email = "Email is required";
103	    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
104	      errors.email = "Enter a valid email address";
105	    setFieldErrors(errors);
106	    return Object.keys(errors).length === 0;
107	  };
108	
109	  const handleSubmit = async (e: React.FormEvent) => {
110	    e.preventDefault();
111	    if (!validate()) return;
112	    if (!jobId) {
113	      toast.error("Invalid application link");
114	      return;
115	    }
116	
117	    setSubmitting(true);
118	    try {
119	      const form = new FormData();
120	      form.append("job_id", jobId);
121	      form.append("name", name.trim());
122	      form.append("email", email.trim().toLowerCase());
123	      if (phone.trim()) form.append("phone", phone.trim());
124	      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
125	      if (resumeFile) form.append("resume", resumeFile);
126	
127	      const { data: sessionData } = await supabase.auth.getSession();
128	      const headers: Record<string, string> = {
129	        // Supabase project URL and anon key from env — required even for anon calls
130	        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
131	      };
132	      if (sessionData.session?.access_token) {
133	        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
134	      } else {
135	        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
136	      }
137	
138	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
139	      const res = await fetch(
140	        `${supabaseUrl}/functions/v1/submit-application`,
141	        {
142	          method: "POST",
143	          headers,
144	          body: form,
145	        }
146	      );
147	
148	      const json = await res.json();
149	      if (!res.ok) {
150	        throw new Error(json.error || "Failed to submit application");
151	      }
152	
153	      setSubmitted(true);
154	    } catch (err: unknown) {
155	      const message =
156	        err instanceof Error ? err.message : "Submission failed. Please try again.";
157	      toast.error(message);
158	    } finally {
159	      setSubmitting(false);
160	    }
161	  };
162	
163	  // ── Success screen ──────────────────────────────────────────────────────
164	  if (submitted) {
165	    return (
166	      <div className="min-h-screen bg-background flex flex-col">
167	        <ApplyHeader />
168	        <main className="flex-1 flex items-center justify-center px-4 py-16">
169	          <div className="w-full max-w-md text-center space-y-6">
170	            <div className="flex justify-center">
171	              <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
172	                <CheckCircle2 className="h-8 w-8 text-emerald-600 dark:text-emerald-400" />
173	              </div>
174	            </div>
175	            <div className="space-y-2">
176	              <h1 className="text-2xl font-semibold tracking-tight">
177	                Application Submitted Successfully!
178	              </h1>
179	              <p className="text-sm text-muted-foreground leading-relaxed">
180	                Thank you! We will review your information and get in touch shortly.
181	              </p>
182	            </div>
183	            <Link
184	              to="/"
185	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
186	            >
187	              Back to Jobs
188	            </Link>
189	          </div>
190	        </main>
191	        <ApplyFooter />
192	      </div>
193	    );
194	  }
195	
196	  // ── Job not found ───────────────────────────────────────────────────────
197	  if (!jobLoading && (jobError || !job || job?.status === "failed")) {
198	    const isClosed = job?.status === "failed";
199	    return (
200	      <div className="min-h-screen bg-background flex flex-col">
201	        <ApplyHeader />
202	        <main className="flex-1 flex items-center justify-center px-4 py-16">
203	          <div className="w-full max-w-md text-center space-y-4">
204	            <div className="flex justify-center">
205	              <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
206	                <Briefcase className="h-7 w-7 text-muted-foreground" />
207	              </div>
208	            </div>
209	            <h1 className="text-xl font-semibold">
210	              {isClosed ? "Applications Closed" : "Job not found"}
211	            </h1>
212	            <p className="text-sm text-muted-foreground">
213	              {isClosed
214	                ? "This position is no longer accepting applications."
215	                : "This application link may have expired or the job no longer exists."}
216	            </p>
217	            <Link
218	              to="/"
219	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
220	            >
221	              Back to Jobs
222	            </Link>
223	          </div>
224	        </main>
225	        <ApplyFooter />
226	      </div>
227	    );
228	  }
229	
230	  return (
231	    <div className="min-h-screen bg-background flex flex-col">
232	      <ApplyHeader />
233	
234	      <main className="flex-1 flex items-start justify-center px-4 py-10">
235	        <div className="w-full max-w-lg">
236	          {/* Job title */}
237	          <div className="mb-8 space-y-1">
238	            {jobLoading ? (
239	              <>
240	                <Skeleton className="h-7 w-64" />
241	                <Skeleton className="h-4 w-40 mt-2" />
242	              </>
243	            ) : (
244	              <>
245	                <h1 className="text-2xl font-semibold tracking-tight leading-tight">
246	                  {job?.title ?? "Apply for this position"}
247	                </h1>
248	                {job?.job_description && (
249	                  <div className="mt-4 rounded-lg border border-border bg-muted/30 p-4 max-h-60 overflow-y-auto">
250	                    <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">
251	                      Job Description
252	                    </h2>
253	                    <p className="text-sm text-foreground whitespace-pre-line leading-relaxed">
254	                      {job.job_description}
255	                    </p>
256	                  </div>
257	                )}
258	                <p className="text-sm text-muted-foreground mt-3">
259	                  Fill in your details below to apply.
260	                </p>
261	              </>
262	            )}
263	          </div>
264	
265	          <form onSubmit={handleSubmit} noValidate className="space-y-5">
266	            {/* Name */}
267	            <div className="space-y-1.5">
268	              <Label htmlFor="apply-name">
269	                Full Name <span className="text-destructive">*</span>
270	              </Label>
271	              <Input
272	                id="apply-name"
273	                type="text"
274	                placeholder="Jane Smith"
275	                value={name}
276	                onChange={(e) => {
277	                  setName(e.target.value);
278	                  if (fieldErrors.name)
279	                    setFieldErrors((prev) => ({ ...prev, name: "" }));
280	                }}
281	                autoComplete="name"
282	                aria-invalid={!!fieldErrors.name}
283	                aria-describedby={fieldErrors.name ? "name-error" : undefined}
284	                disabled={submitting}
285	              />
286	              {fieldErrors.name && (
287	                <p id="name-error" className="text-xs text-destructive">
288	                  {fieldErrors.name}
289	                </p>
290	              )}
291	            </div>
292	
293	            {/* Email */}
294	            <div className="space-y-1.5">
295	              <Label htmlFor="apply-email">
296	                Email Address <span className="text-destructive">*</span>
297	              </Label>
298	              <Input
299	                id="apply-email"
300	                type="email"
301	                placeholder="jane@example.com"
302	                value={email}
303	                onChange={(e) => {
304	                  setEmail(e.target.value);
305	                  if (fieldErrors.email)
306	                    setFieldErrors((prev) => ({ ...prev, email: "" }));
307	                }}
308	                autoComplete="email"
309	                aria-invalid={!!fieldErrors.email}
310	                aria-describedby={fieldErrors.email ? "email-error" : undefined}
311	                disabled={submitting}
312	              />
313	              {fieldErrors.email && (
314	                <p id="email-error" className="text-xs text-destructive">
315	                  {fieldErrors.email}
316	                </p>
317	              )}
318	            </div>
319	
320	            {/* Phone */}
321	            <div className="space-y-1.5">
322	              <Label htmlFor="apply-phone">Phone Number</Label>
323	              <Input
324	                id="apply-phone"
325	                type="tel"
326	                placeholder="+1 555 000 0000"
327	                value={phone}
328	                onChange={(e) => setPhone(e.target.value)}
329	                autoComplete="tel"
330	                disabled={submitting}
331	              />
332	            </div>
333	
334	            {/* Resume Upload */}
335	            <div className="space-y-1.5">
336	              <Label>Resume / CV <span className="text-xs font-normal text-muted-foreground">(optional)</span></Label>
337	              {resumeFile ? (
338	                <div className="flex items-center gap-3 rounded-lg border border-border bg-secondary/40 px-4 py-3">
339	                  <FileText className="h-5 w-5 text-primary shrink-0" />
340	                  <span className="flex-1 text-sm truncate">{resumeFile.name}</span>
341	                  <button
342	                    type="button"
343	                    onClick={() => {
344	                      setResumeFile(null);
345	                      if (fileInputRef.current) fileInputRef.current.value = "";
346	                    }}
347	                    className="text-muted-foreground hover:text-destructive transition-colors"
348	                    aria-label="Remove resume"
349	                    disabled={submitting}
350	                  >
351	                    <X className="h-4 w-4" />
352	                  </button>
353	                </div>
354	              ) : (
355	                <div
356	                  role="button"
357	                  tabIndex={0}
358	                  aria-label="Upload resume — PDF, DOCX, DOC, RTF, or TXT, max 10MB"
359	                  onKeyDown={(e) => {
360	                    if (e.key === "Enter" || e.key === " ")
361	                      fileInputRef.current?.click();
362	                  }}
363	                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-200 flex flex-col items-center gap-2 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
364	                    dragOver
365	                      ? "border-primary bg-primary/5 scale-[1.01]"
366	                      : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
367	                  }`}
368	                  onDragOver={(e) => {
369	                    e.preventDefault();
370	                    setDragOver(true);
371	                  }}
372	                  onDragLeave={() => setDragOver(false)}
373	                  onDrop={handleDrop}
374	                  onClick={() => fileInputRef.current?.click()}
375	                >
376	                  <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center">
377	                    <Upload className="h-5 w-5 text-primary" />
378	                  </div>
379	                  <p className="text-sm font-medium text-foreground">
380	                    Drop your resume here or{" "}
381	                    <span className="text-primary">click to browse</span>
382	                  </p>
383	                  <p className="text-xs text-muted-foreground">
384	                    PDF, DOCX, DOC, RTF, TXT · Max 10MB
385	                  </p>
386	                  <input
387	                    ref={fileInputRef}
388	                    id="resume-input"
389	                    type="file"
390	                    className="hidden"
391	                    accept=".pdf,.docx,.doc,.rtf,.txt"
392	                    onChange={(e) => {
393	                      const file = e.target.files?.[0];
394	                      if (file) handleFileSelect(file);
395	                    }}
396	                    disabled={submitting}
397	                  />
398	                </div>
399	              )}
400	            </div>
401	
402	            {/* LinkedIn URL */}
403	            <div className="space-y-1.5">
404	              <Label htmlFor="apply-linkedin" className="flex items-center gap-1.5">
405	                LinkedIn Profile
406	                <span className="text-xs font-normal text-muted-foreground">
407	                  (optional)
408	                </span>
409	              </Label>
410	              <div className="relative">
411	                <Input
412	                  id="apply-linkedin"
413	                  type="url"
414	                  placeholder="https://linkedin.com/in/jane-smith"
415	                  value={linkedinUrl}
416	                  onChange={(e) => setLinkedinUrl(e.target.value)}
417	                  className="pr-9"
418	                  disabled={submitting}
419	                />
420	                <ExternalLink className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
421	              </div>
422	            </div>
423	
424	            {/* Submit */}
425	            <Button
426	              type="submit"
427	              className="w-full gap-2"
428	              size="lg"
429	              disabled={submitting}
430	            >
431	              {submitting ? (
432	                <>
433	                  <Loader2 className="h-4 w-4 animate-spin" />
434	                  Submitting…
435	                </>
436	              ) : (
437	                "Submit Application"
438	              )}
439	            </Button>
440	          </form>
441	        </div>
442	      </main>
443	
444	      <ApplyFooter />
445	    </div>
446	  );
447	}
448	
449	function ApplyHeader() {
450	  return (
451	    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
452	      <div className="max-w-2xl mx-auto px-4 py-4 flex items-center gap-2">
453	        <Link
454	          to="/"
455	          className="flex items-center gap-2 text-sm font-semibold text-foreground hover:text-primary transition-colors"
456	        >
457	          <div className="w-6 h-6 rounded bg-primary flex items-center justify-center">
458	            <span className="text-[11px] font-bold text-primary-foreground">R</span>
459	          </div>
460	          Rankora
461	        </Link>
462	      </div>
463	    </header>
464	  );
465	}
466	
467	function ApplyFooter() {
468	  return (
469	    <footer className="py-6 text-center">
470	      <p className="text-xs text-muted-foreground">
471	        Powered by{" "}
472	        <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">
473	          Rankora
474	        </Link>
475	      </p>
476	    </footer>
477	  );
478	}
