38	      <div className="px-4 py-4">
39	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
40	      </div>
41	      <div className="border-t border-border" />
42	      <div className="p-3 space-y-2">
43	        {[1, 2, 3, 4].map((i) => (
44	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
45	        ))}
46	      </div>
47	    </div>
48	    {/* Content area skeleton */}
49	    <div className="flex-1 flex flex-col min-w-0">
50	      {/* Header skeleton */}
51	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
52	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
53	        <div className="flex items-center gap-3">
54	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
55	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
56	        </div>
57	      </div>
58	      {/* Body skeleton */}
59	      <div className="flex-1 overflow-y-auto p-6">
60	        <div className="max-w-5xl mx-auto space-y-4">
61	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
62	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
63	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
64	            {[1, 2, 3, 4].map((i) => (
65	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
66	            ))}
67	          </div>
68	        </div>
69	      </div>
70	    </div>
71	  </div>
72	);
73	
74	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
75	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
76	  const { isAdmin, loading } = useAuth();
77	
78	  // Don't block rendering while loading — only gate when we know maintenance is on
79	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
80	  return <>{children}</>;
81	};
82	
83	const RootRoute = () => {
84	  const { user, loading } = useAuth();
85	  if (loading) return <PageLoader />;
86	  return user ? <Index /> : <LandingPage />;
87	};
88	
89	const App = () => (
90	  <QueryClientProvider client={queryClient}>
91	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
92	      <AuthProvider>
93	        <TooltipProvider>
94	          <Sonner />
95	          <BrowserRouter>
96	            <SeoHead />
97	            <Suspense fallback={<PageLoader />}>
98	              <Routes>
99	                {/* Public apply page — outside MaintenanceGate so candidates can always apply */}
100	                <Route path="/apply/:jobId" element={<Apply />} />
101	                <Route path="*" element={
102	                  <MaintenanceGate>
103	                    <Routes>
104	                      <Route path="/auth" element={<Auth />} />
105	                      <Route path="/" element={<RootRoute />} />
106	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
107	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
108	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
109	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
110	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
111	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
